-- Guard: approved versions are immutable and only drafts can be deleted
CREATE OR REPLACE FUNCTION sdm.guard_static_version() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  locked text[] := ARRAY['APPROVED','ACTIVE','DEPRECATED','PUBLISHED','EFFECTIVE','WITHDRAWN','RETIRED'];
  mutable text[] := ARRAY['record_status','effective_to','row_version'];
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.record_status <> 'DRAFT' THEN
      RAISE EXCEPTION '% %: only draft records can be deleted; deprecate or retire instead (SDM-007)', TG_TABLE_NAME, OLD.code;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.record_status = ANY (locked)
     AND (to_jsonb(NEW) - mutable) IS DISTINCT FROM (to_jsonb(OLD) - mutable) THEN
    RAISE EXCEPTION '% % v%: approved versions are immutable; create a new version (SDM-002)', TG_TABLE_NAME, OLD.code, OLD.version;
  END IF;
  RETURN NEW;
END $$;

-- Tables

-- Experience · Portals and partner channels · Channel definitions
CREATE TABLE channel.cfg_channel_definitions (
  id                             uuid NOT NULL DEFAULT gen_random_uuid(),
  tenant_id                      uuid NOT NULL,
  code                           varchar(120) NOT NULL,
  version                        integer NOT NULL DEFAULT 1,
  effective_from                 date NOT NULL DEFAULT CURRENT_DATE,
  effective_to                   date,
  record_status                  varchar(20) NOT NULL DEFAULT 'DRAFT',
  supersedes_id                  uuid,
  labels                         jsonb,
  description                    text,
  record_source                  varchar(60),
  record_source_version          varchar(30),
  external_mappings              jsonb,
  record_class                   varchar(20) NOT NULL DEFAULT 'INTERNAL',
  sort_order                     integer,
  display_flags                  jsonb,
  change_request_id              uuid,
  created_at                     timestamptz NOT NULL DEFAULT now(),
  created_by                     varchar(80) NOT NULL,
  approved_at                    timestamptz,
  approved_by                    varchar(80),
  change_reason                  text,
  row_version                    bigint NOT NULL DEFAULT 1,
  channel_code                   varchar(12) NOT NULL,
  audience                       varchar(40) NOT NULL,
  name                           varchar(80) NOT NULL,
  enabled_products               text[],
  enabled_transactions           text[],
  branding_theme                 varchar(80),
  CONSTRAINT cfg_channel_definitions_pk PRIMARY KEY (id),
  CONSTRAINT cfg_channel_definitions_bkey UNIQUE NULLS NOT DISTINCT (tenant_id, code, version),
  CONSTRAINT cfg_channel_definitions_stat CHECK (record_status IN ('DRAFT', 'VALIDATED', 'SUBMITTED', 'APPROVED', 'PUBLISHED', 'EFFECTIVE', 'WITHDRAWN', 'RETIRED')),
  CONSTRAINT cfg_channel_definitions_dates CHECK (effective_to IS NULL OR effective_to > effective_from),
  CONSTRAINT cfg_channel_definitions_rcls CHECK (record_class IN ('PUBLIC','INTERNAL','CONFIDENTIAL','PERSONAL','HIGHLY_SENSITIVE')),
  CONSTRAINT cfg_channel_definitions_ck1 CHECK (audience IN ('STAFF', 'BROKER', 'CUSTOMER', 'PROVIDER', 'PARTNER')),
  CONSTRAINT cfg_channel_definitions_nolap EXCLUDE USING gist (
    (COALESCE(tenant_id, '00000000-0000-0000-0000-000000000000'::uuid)) WITH =, code WITH =,
    daterange(effective_from, effective_to, '[)') WITH &&)
    WHERE (record_status IN ('APPROVED', 'PUBLISHED', 'EFFECTIVE'))
);

