ALTER TABLE channel.cfg_channel_definitions ENABLE ROW LEVEL SECURITY;
ALTER TABLE channel.cfg_channel_definitions FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON channel.cfg_channel_definitions
  USING (tenant_id = current_setting('app.tenant_id')::uuid)
  WITH CHECK (tenant_id = current_setting('app.tenant_id')::uuid);
